//! The application models the conversions use: a copy of the types DB2CRUD read.

/// ProductStatus, as the application has it.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ProductStatus {
    Draft,
    Live,
}

/// Customer, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Customer {
    pub id: i64,
    pub email: String,
    pub password_hash: String,
    pub created_at: chrono::DateTime<chrono::Utc>,
}

/// CategoryDto, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct CategoryDto {
    pub id: i32,
    pub name: String,
}

/// Product, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Product {
    pub id: i64,
    pub name: String,
    pub price: rust_decimal::Decimal,
    pub status: ProductStatus,
    pub category_name: String,
    pub tag_ids: Vec<i32>,
}

/// TagEntity, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct TagEntity {
    pub id: i32,
    pub label: String,
}

