//! Conversions between the application models and the "categories" table: what the service takes and returns.

use crate::application_models::CategoryDto;
use crate::entities::category::Category;

/// A CategoryDto as the categories table takes it.
pub fn category_dto_to_category(model: &CategoryDto) -> Category {
    Category {
        name: Some(model.name.clone()),
        ..Default::default()
    }
}

/// A row of the categories table as a CategoryDto.
pub fn category_to_category_dto(row: &Category) -> CategoryDto {
    CategoryDto {
        id: row.id.expect("id is set"),
        name: row.name.clone().expect("name is set"),
    }
}

