//! Conversions between the application models and the "products" table: what the service takes and returns.

use crate::application_models::{Product as ProductModel, ProductStatus};
use crate::entities::product::Product;
use crate::errors::DomainError;
use crate::unit_of_work::UnitOfWork;

/// A Product as the products table takes it.
pub async fn product_model_to_product(model: &ProductModel, uow: &dyn UnitOfWork) -> Result<Product, DomainError> {
    let category = uow.categories().find_by_name(model.category_name.clone()).await?
        .ok_or_else(|| DomainError::not_found("Category", &model.category_name))?;
    Ok(
        Product {
            category_id: category.id,
            name: Some(model.name.clone()),
            price: Some(model.price),
            status: Some(match model.status { ProductStatus::Draft => "draft".to_string(), ProductStatus::Live => "live".to_string() }),
            ..Default::default()
        }
    )
}

/// A row of the products table as a Product.
pub async fn product_to_product_model(row: &Product, uow: &dyn UnitOfWork) -> Result<ProductModel, DomainError> {
    let category = uow.categories().find_by_id(row.category_id.expect("category_id is set")).await?;
    Ok(
        ProductModel {
            id: row.id.expect("id is set"),
            name: row.name.clone().expect("name is set"),
            price: row.price.expect("price is set"),
            status: match row.status.clone().expect("status is set").as_str() { "draft" => ProductStatus::Draft, "live" => ProductStatus::Live, _ => panic!("No ProductStatus for this value") },
            category_name: category.as_ref().and_then(|row| row.name.clone()).expect("categories.name is set"),
            tag_ids: uow.product_tags().list_by_product_id(row.id.expect("id is set")).await?.into_iter().map(|item| item.tag_id.expect("tag_id is set")).collect(),
        }
    )
}

