    #[sea_orm(column_type = "String(StringLen::N(100))")]
    pub name: String,
    #[sea_orm(column_type = "Decimal(Some((10, 2)))")]
    pub price: rust_decimal::Decimal,
    #[sea_orm(column_type = "String(StringLen::N(10))", default_value = "draft")]
    pub status: String,
}

#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
pub enum Relation {
    #[sea_orm(belongs_to = "crate::entities::category_table::Entity", from = "Column::CategoryId", to = "crate::entities::category_table::Column::Id")]
