//! The service of the "categories" table, on the in-memory repositories.

use seaorm_sqlite_conversions_import::common::Patch;
use seaorm_sqlite_conversions_import::errors::DomainError;
use seaorm_sqlite_conversions_import::services::category::{CategoryChanges, CategoryService};
use seaorm_sqlite_conversions_import::unit_of_work::MemoryUnitOfWork;
use std::sync::Arc;
use super::factories;

#[tokio::test]
async fn creates_a_valid_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CategoryService::new(uow.clone());
    let row = factories::new_category(1);
    let created = service.create_category(row).await.expect("a create");
    let found = service.get_category(created.id.expect("id is set")).await.expect("a read");
    assert_eq!(created.id, found.id);
}

#[tokio::test]
async fn refuses_a_missing_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CategoryService::new(uow.clone());
    let mut row = factories::new_category(1);
    row.name = None;
    let error = service.create_category(row).await.expect_err("a refusal");
    let DomainError::ValidationFailed { errors, .. } = &error else { panic!("{error}") };
    assert_eq!(vec!["name"], errors.iter().map(|error| error.field.as_str()).collect::<Vec<_>>());
}

#[tokio::test]
async fn refuses_a_repeated_unique_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CategoryService::new(uow.clone());
    let row = factories::new_category(1);
    let first = service.create_category(row).await.expect("a create");
    let mut again = factories::new_category(2);
    again.name = first.name.clone();
    assert!(matches!(service.create_category(again).await, Err(DomainError::Conflict { .. })));
}

#[tokio::test]
async fn keeps_its_own_unique_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CategoryService::new(uow.clone());
    let row = factories::new_category(1);
    let created = service.create_category(row.clone()).await.expect("a create");
    let updated = service.update_category(created.id.expect("id is set"), CategoryChanges { name: Patch::Set(created.name.clone()), ..Default::default() }).await.expect("an update");
    assert_eq!(created.name, updated.name);
}

#[tokio::test]
async fn says_when_a_row_is_missing() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CategoryService::new(uow.clone());
    assert!(matches!(service.get_category(999999).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn deletes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CategoryService::new(uow.clone());
    let row = factories::new_category(1);
    let created = service.create_category(row).await.expect("a create");
    service.delete_category(created.id.expect("id is set")).await.expect("a delete");
    assert!(matches!(service.get_category(created.id.expect("id is set")).await, Err(DomainError::NotFound { .. })));
}

