//! The test database: TEST_DATABASE_URL, or SQLite in a new temporary file, created from the SeaORM entities before every test.

use sea_orm::{ConnectionTrait, Database, DatabaseConnection, Schema, Statement};
use seaorm_sqlite_conversions_import::entities::{category_table as categories_table, customer_table as customers_table, product_table as products_table, product_tag_table as product_tags_table, tag_table as tags_table};
use seaorm_sqlite_conversions_import::unit_of_work::SqlUnitOfWork;
use std::sync::atomic::{AtomicUsize, Ordering};
use tokio::sync::{Mutex, MutexGuard};

/// Every test empties the same database: they take turns
static TURN: Mutex<()> = Mutex::const_new(());

/// A connection to the test database.
async fn connect() -> DatabaseConnection {
    let url = std::env::var("TEST_DATABASE_URL").unwrap_or_else(|_| {
        // A new file for every test: SQLite in memory would be another database on every connection
        static FILES: AtomicUsize = AtomicUsize::new(0);
        let name = format!("seaorm_sqlite_conversions_import-{}-{}.db", std::process::id(), FILES.fetch_add(1, Ordering::SeqCst));
        format!("sqlite://{}?mode=rwc", std::env::temp_dir().join(name).display())
    });
    Database::connect(&url).await.expect("the test database")
}

/// The repositories over the test database, with every table dropped and created again, and the turn of the test
/// that holds it.
pub async fn open() -> (MutexGuard<'static, ()>, SqlUnitOfWork) {
    let turn = TURN.lock().await;
    let db = connect().await;
    db.execute_unprepared("DROP TABLE IF EXISTS \"product_tags\"").await.expect("DROP TABLE IF EXISTS \"product_tags\"");
    db.execute_unprepared("DROP TABLE IF EXISTS \"tags\"").await.expect("DROP TABLE IF EXISTS \"tags\"");
    db.execute_unprepared("DROP TABLE IF EXISTS \"products\"").await.expect("DROP TABLE IF EXISTS \"products\"");
    db.execute_unprepared("DROP TABLE IF EXISTS \"categories\"").await.expect("DROP TABLE IF EXISTS \"categories\"");
    db.execute_unprepared("DROP TABLE IF EXISTS \"customers\"").await.expect("DROP TABLE IF EXISTS \"customers\"");
    Schema::new(db.get_database_backend())
        .builder()
        .register(customers_table::Entity)
        .register(categories_table::Entity)
        .register(products_table::Entity)
        .register(tags_table::Entity)
        .register(product_tags_table::Entity)
        .apply(&db)
        .await
        .expect("the tables");
    (turn, SqlUnitOfWork::new(db))
}

#[tokio::test]
async fn is_sqlite() {
    let _turn = TURN.lock().await;
    let db = connect().await;
    let row = db.query_one_raw(Statement::from_string(db.get_database_backend(), "SELECT sqlite_version()")).await.expect("a query").expect("a row");
    let value: String = row.try_get_by_index(0).expect("a value");
    assert!(value.starts_with("3."));
}

