//! Rows for the tests: valid values for every column, and the rows they point to.

// Not every test uses every factory
#![allow(dead_code)]

use seaorm_sqlite_conversions_import::entities::category::Category;
use seaorm_sqlite_conversions_import::entities::customer::Customer;
use seaorm_sqlite_conversions_import::entities::product::Product;
