use seaorm_sqlite_conversions_import::entities::tag::Tag;
use seaorm_sqlite_conversions_import::unit_of_work::UnitOfWork;

/// A valid Customer that is not stored yet; n makes its unique values differ.
pub fn new_customer(n: i32) -> Customer {
    Customer {
        email: Some(format!("email-{n}")),
        password_hash: Some(format!("passwordhash-{n}")),
        ..Default::default()
    }
}

/// A stored Customer.
pub async fn add_customer(uow: &dyn UnitOfWork, n: i32) -> Customer {
    let entity = new_customer(n);
    uow.customers().insert(entity).await.expect("a stored Customer")
}

/// A valid Category that is not stored yet; n makes its unique values differ.
pub fn new_category(n: i32) -> Category {
    Category {
        name: Some(format!("name-{n}")),
        ..Default::default()
    }
}

/// A stored Category.
pub async fn add_category(uow: &dyn UnitOfWork, n: i32) -> Category {
    let entity = new_category(n);
    uow.categories().insert(entity).await.expect("a stored Category")
}

/// A valid Product that is not stored yet; n makes its unique values differ.
pub fn new_product(n: i32) -> Product {
    Product {
        name: Some(format!("name-{n}")),
        price: Some(rust_decimal::Decimal::new(i64::from(n % 10000) * 100 + 50, 2)),
        status: Some("draft".to_string()),
        ..Default::default()
    }
}

/// A stored Product, with the rows it points to.
pub async fn add_product(uow: &dyn UnitOfWork, n: i32) -> Product {
    let parent0 = add_category(uow, n).await;
    let mut entity = new_product(n);
    entity.category_id = parent0.id;
    uow.products().insert(entity).await.expect("a stored Product")
}

/// A valid Tag that is not stored yet; n makes its unique values differ.
pub fn new_tag(n: i32) -> Tag {
    Tag {
        label: Some(format!("label-{n}")),
        ..Default::default()
    }
}

/// A stored Tag.
pub async fn add_tag(uow: &dyn UnitOfWork, n: i32) -> Tag {
    let entity = new_tag(n);
    uow.tags().insert(entity).await.expect("a stored Tag")
}

/// A valid ProductTag that is not stored yet; n makes its unique values differ.
pub fn new_product_tag(_n: i32) -> ProductTag {
    ProductTag {
        ..Default::default()
    }
}

/// A stored ProductTag, with the rows it points to.
pub async fn add_product_tag(uow: &dyn UnitOfWork, n: i32) -> ProductTag {
    let parent0 = add_product(uow, n).await;
    let parent1 = add_tag(uow, n).await;
    let mut entity = new_product_tag(n);
    entity.product_id = parent0.id;
    entity.tag_id = parent1.id;
    uow.product_tags().insert(entity).await.expect("a stored ProductTag")
}

